insert into safebus_private.authority_reference_directory(authority_code,official_name,authority_category,address,city,province,postal_code,email,phone,website_url,source_url,source_extract_date,available,imported_at)
  select authority_code,official_name,authority_category,address,city,province,postal_code,email,phone,website_url,source_url,source_extract_date,available,now() from safebus_authority_import
on conflict(authority_code) do update set official_name=excluded.official_name,authority_category=excluded.authority_category,address=excluded.address,city=excluded.city,province=excluded.province,postal_code=excluded.postal_code,email=excluded.email,phone=excluded.phone,website_url=excluded.website_url,source_url=excluded.source_url,source_extract_date=excluded.source_extract_date,available=excluded.available,imported_at=now();
update safebus_private.authority_reference_directory d set available=false,imported_at=now()
  where d.available and not exists(select 1 from safebus_authority_import i where i.authority_code=d.authority_code);
insert into safebus_private.authority_directory_import_state(singleton,source_sha256,source_extract_date,record_count)
values(true,'7ad60759cc326466260c0072d3613c27fa755ff13ad2edc64d391ffbf11204ee','2026-10-24',445)
on conflict(singleton) do update set source_sha256=excluded.source_sha256,source_extract_date=excluded.source_extract_date,
  record_count=excluded.record_count,imported_at=now();
